function validate([s, k]) {
  if (s.length < 1 || s.length > 200) return 's needs 1 to 200 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (k < 1 || k > 200) return 'k is between 1 and 200.';
  return null;
}

