function longestPalindromicSubsequence(s, k) {
  const n = s.length;
  // prev[j][c]: the answer for s[i + 1..j] with at most c operations (the previous start's row).
  let prev = Array.from({ length: n }, () => new Array(k + 1).fill(0));
  for (let i = n - 1; i >= 0; i--) {
    // dp[j][c]: longest palindromic subsequence of s[i..j] using at most c operations.
    const dp = Array.from({ length: n }, () => new Array(k + 1).fill(0));
    dp[i].fill(1);
    for (let j = i + 1; j < n; j++) {
      const gap = Math.abs(s.charCodeAt(i) - s.charCodeAt(j));
      const cost = Math.min(gap, 26 - gap);
      const dropFirst = prev[j];
      const dropLast = dp[j - 1];
      const inside = prev[j - 1];
      for (let c = 0; c <= k; c++) {
        dp[j][c] = Math.max(dropFirst[c], dropLast[c]);
        if (cost <= c) {
          dp[j][c] = Math.max(dp[j][c], inside[c - cost] + 2);
        }
      }
    }
    prev = dp;
  }
  return prev[n - 1][k];
}

brute:
function longestPalindromicSubsequence(s, k) {
  // Try every subsequence: it can be made a palindrome by changing one letter of each mirrored pair
  // into the other, walking the shorter way around the alphabet.
  const steps = (from, to) => Math.min((to - from + 26) % 26, (from - to + 26) % 26);
  const n = s.length;
  let best = 0;
  for (let mask = 1; mask < 1 << n; mask++) {
    const picked = [];
    for (let i = 0; i < n; i++) if (mask & (1 << i)) picked.push(s.charCodeAt(i) - 97);
    let used = 0;
    for (let a = 0, b = picked.length - 1; a < b; a++, b--) used += steps(picked[a], picked[b]);
    if (used <= k) best = Math.max(best, picked.length);
  }
  return best;
}

