function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  const n = size === 'large' ? 200 : 1 + pick(12);
  // Few distinct letters give many equal pairs; letters near both ends of the alphabet exercise the wrap-around.
  const alphabet = ['abcdefghijklmnopqrstuvwxyz', 'abcdefghijklmnopqrstuvwxyz', 'ab', 'abc', 'ayz', 'abyz', 'amz', 'aeiou', 'xyzab'][pick(9)];
  const s = Array.from({ length: n }, () => alphabet[pick(alphabet.length)]).join('');
  // Large budgets stay at most 100, so an O(n^2 * k) solution runs comfortably within the local time limit.
  const k = size === 'large' ? [100, 1 + pick(100), 1 + pick(20)][pick(3)] : [1, 1 + pick(4), 1 + pick(20), 1 + pick(200)][pick(4)];
  return [s, k];
}
